// ================================================================ #150 二阶段：apply 内部数据面与路由分支

import { existsSync, readFileSync, readdirSync } from "node:fs";

/** 构造标准 fake ctx：收集路由与 disposer。 */
function makeCtx(over: {
  llm?: unknown;
} = {}) {
  const routes: Array<Record<string, unknown>> = [];
  const disposers: Array<() => void> = [];
  const ctx = {
    logger: { warn: () => {} },
    webServer: { register(route: Record<string, unknown>) { routes.push(route); return () => {}; } },
    llm: over.llm !== undefined ? over.llm : { listProviders() { return []; } },
    fiber: { state: "active" },
    inject: (deps: unknown, cb: (s: unknown) => void) => { cb({ settings: {} }); },
    effect(fn: () => unknown) {
      const d = fn();
      if (typeof d === "function") disposers.push(d as () => void);
      return typeof d === "function" ? d : () => {};
    },
  };
  return { ctx, routes, disposers };
}

/** 合法用户适配器 mjs 文本。 */
function adapterMjs(name: string, body = "{ v: 1 }"): string {
  return `
export const version = ${ADAPTER_CONTRACT_VERSION};
export const name = ${JSON.stringify(name)};
export const label = ${JSON.stringify(name)};
export const providers = ["${OPENCODE_GO_PROVIDER}"];
export async function fetchData() { return ${body}; }
export function formatCapsule() { return "<span>${name}</span>"; }
export function formatPanel() { return "<p>${name}</p>"; }
`;
}

/** 轮询直到条件成立或超时（防 flake：不使用固定 sleep 判定）。 */
async function pollUntil(cond: () => boolean, timeoutMs = 2000): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (cond()) return true;
    await new Promise((r) => setTimeout(r, 10));
  }
  return cond();
}

const routeOf = (routes: Array<Record<string, unknown>>, path: string) =>
  routes.find((r) => r.path === path) as { handler: (req: unknown, res: unknown) => Promise<void> | void } | undefined;

// ---------------------------------------------------------------- stats/history 路由围栏与数据面

{
  const dir = mkdtempSync(join(tmpdir(), "dou-stats-"));
  const goodFile = join(dir, "good.mjs");
  writeFileSync(goodFile, adapterMjs("stats-adp"), "utf8");
  const { ctx, routes } = makeCtx();
  await apply(ctx, {
    adapter: goodFile, autoReload: false,
    apiKey: "sk", apiEndpoint: "http://127.0.0.1:9",
    historyDir: join(dir, "hist"),
  });

  // stats：403 非 loopback / 405 非 GET
  const stats = routeOf(routes, ROUTES.stats);
  assert.ok(stats, "stats 路由已注册");
  const res403 = makeRes();
  await stats.handler(fakeReq({ headers: { host: "evil.example" } }), res403);
  assert.equal(res403._code(), 403, "stats 非 loopback 403");
  const res405 = makeRes();
  await stats.handler(fakeReq({ method: "POST" }), res405);
  assert.equal(res405._code(), 405, "stats POST 405");

  // history：403 / 405 / 无候选 no-adapter / days clamp
  const historyR = routeOf(routes, ROUTES.history);
  assert.ok(historyR, "history 路由已注册");
  const h403 = makeRes();
  await historyR.handler(fakeReq({ headers: { host: "x" } }), h403);
  assert.equal(h403._code(), 403, "history 非 loopback 403");

  // 无启用适配器（清空选择后）→ 结构化 no-adapter
  const hNoAdp = makeRes();
  await historyR.handler(fakeReq({ url: `${ROUTES.history}?provider=ghost` }), hNoAdp);
  const noAdpBody = JSON.parse(hNoAdp._body());
  assert.equal(noAdpBody.reason, "no-adapter", "无候选 provider 报 no-adapter");
  assert.equal(noAdpBody.panelHtml, null, "无候选不带占位 HTML");

  // days 参数：合法窗口取 min(days, maxAgeDays)
  const hDays = makeRes();
  await historyR.handler(fakeReq({ url: `${ROUTES.history}?days=7` }), hDays);
  const okBody = JSON.parse(hDays._body());
  assert.equal(okBody.plugin, "dsh-provider-usage", "history 正常响应 plugin 字段");
  assert.equal(okBody.adapterName, "stats-adp", "用户适配器注册后默认成为启用者");
  assert.equal(typeof okBody.range.start, "number", "range.start 数字");
}

// ---------------------------------------------------------------- getStats：缓存命中 / busy / 未配置

{
  const dir = mkdtempSync(join(tmpdir(), "dou-getstats-"));
  // 隔离 DSH_HOME：避免读到真实环境的 user-adapters.json / adapter-state.json，
  // 否则启动预热会对真实适配器逐个取数（每个最长 fetchTimeoutMs）长期持锁。
  const savedDshHome = process.env.DSH_HOME;
  process.env.DSH_HOME = join(dir, "dshhome");
  mkdirSync(process.env.DSH_HOME, { recursive: true });
  try {
    // fetchData 带 IO 延迟（80ms）的适配器：为 busy 竞争提供持锁窗口
    const slowFile = join(dir, "slow.mjs");
    writeFileSync(slowFile, `
export const version = ${ADAPTER_CONTRACT_VERSION};
export const name = "slow-adp";
export const providers = ["prov-slow"];
export async function fetchData() {
  await new Promise((r) => setTimeout(r, 80));
  return { v: 42 };
}
export function formatCapsule() { return "<span>s</span>"; }
export function formatPanel() { return "<p>s</p>"; }
`, "utf8");
    const { ctx, routes } = makeCtx();
    await apply(ctx, {
      adapter: slowFile, autoReload: false,
      apiKey: "sk", apiEndpoint: "http://127.0.0.1:9",
      historyDir: join(dir, "hist"),
    });
    const stats = routeOf(routes, ROUTES.stats) as { handler: (req: unknown, res: unknown) => Promise<void> };
    const selectR = routeOf(routes, ROUTES.select) as { handler: (req: unknown, res: unknown) => Promise<void> };
    const clearCache = async (): Promise<void> => {
      // select 成功路径自带 cache.clear()：清空再重启用，两次都触发清空
      await selectR.handler(fakeReq({ method: "POST", body: JSON.stringify({ provider: "prov-slow", adapterName: null }) }), makeRes());
      await selectR.handler(fakeReq({ method: "POST", body: JSON.stringify({ provider: "prov-slow", adapterName: "slow-adp" }) }), makeRes());
    };
    const askStats = async (): Promise<Record<string, unknown>> => {
      const r = makeRes();
      await stats.handler(fakeReq({ url: `${ROUTES.stats}?provider=prov-slow` }), r);
      return JSON.parse(r._body()) as Record<string, unknown>;
    };

    // 确定性等待启动预热结束：warmup 对 enabledProviders 串行取数，内置
    // opencode-go 走真实网络（最长 fetchTimeoutMs=5000ms），prov-slow 是最后一个。
    // 轮询中遇到 cached 即证明预热已对 prov-slow 写入缓存（整条链必然走完）；
    // 遇到 busy 继续等；cached 出现后清缓存，随后的请求必为 fresh 且无飞行任务。
    const deadline = Date.now() + 20000;
    let warmed = false;
    while (Date.now() < deadline) {
      const b = await askStats();
      if (b.reason === "busy") { await new Promise((r2) => setTimeout(r2, 40)); continue; }
      warmed = true; // cached 或 fresh：预热已完成 prov-slow（链尾）
      break;
    }
    assert.equal(warmed, true, "启动预热在时限内完成");
    await clearCache();

    // 第一次取数：fresh + 历史落盘（此时无任何后台取数干扰）
    const b1 = await askStats();
    assert.equal(b1.status, "fresh", "清缓存后首次取数 fresh");
    assert.equal(b1.capsuleHtml, "<span>s</span>", "胶囊来自适配器");
    const histDir = join(dir, "hist", "prov-slow", "slow-adp");
    const landed = await pollUntil(() => existsSync(histDir) && readdirSync(histDir).length > 0);
    assert.equal(landed, true, "fresh 数据落盘历史 JSONL");

    // 第二次：缓存命中（TTL 内）
    const b2 = await askStats();
    assert.equal(b2.status, "cached", "TTL 内二次请求 cached");

    // busy：清缓存后发起长取数（fetchData 80ms），15ms 后并发同 provider 请求：
    // 无缓存 + 锁忙 → reason=busy stale。此刻 warmup 已结束、60s 内不会重启，
    // 竞争窗口完全由测试控制。
    await clearCache();
    const pFirst = stats.handler(fakeReq({ url: `${ROUTES.stats}?provider=prov-slow` }), makeRes());
    void pFirst.catch(() => {});
    await new Promise((r2) => setTimeout(r2, 15)); // 让首个请求进入 runExclusive 并持锁
    const bBusy = await askStats();
    assert.equal(bBusy.reason, "busy", "锁内并发请求报 busy");
    assert.equal(bBusy.status, "stale", "busy 响应状态 stale");
    assert.equal(bBusy.configured, true, "busy ≠ 未配置");
    assert.equal(bBusy.adapterName, "slow-adp", "busy 响应携带目标 provider 启用适配器名");
    await pFirst;

    // no-enabled-adapter：候选存在但被显式清空（select 清空后 cache.clear()）
    await selectR.handler(fakeReq({
      method: "POST",
      body: JSON.stringify({ provider: "prov-slow", adapterName: null }),
    }), makeRes());
    const bNoEn = await askStats();
    assert.equal(bNoEn.reason, "no-enabled-adapter", "候选存在但清空启用报 no-enabled-adapter");
    assert.equal(bNoEn.ok, false, "未配置语义 ok=false");
    assert.equal(bNoEn.configured, false, "configured=false");
  } finally {
    if (savedDshHome === undefined) delete process.env.DSH_HOME;
    else process.env.DSH_HOME = savedDshHome;
  }
}

// ---------------------------------------------------------------- fetchWithTimeout 边界（#150 二阶段）

// 本文件是 tap 流程最后一个模块：fetchWithTimeout 硬编码读取全局 fetch，
// 注入窗口必须放在不会再被后续模块 TLA 恢复改写的位置（此前置于 unit-contract，
// 其 TLA 让 v1 先行求值并在注入窗口内改写全局 fetch，实证互相污染）。
{
  const savedFetch = globalThis.fetch;
  try {
    // 快路径：远小于超时的延迟 -> 正常拿到注入实现的返回值
    let fastCalls = 0;
    globalThis.fetch = (async (url: unknown, opts: { signal?: AbortSignal }) => {
      fastCalls += 1;
      await new Promise((r) => setTimeout(r, 5));
      return { status: 200, ok: true, url, aborted: opts?.signal?.aborted ?? null };
    }) as unknown as typeof fetch;
    const okRes = await fetchWithTimeout("https://gw.test/fast", 1000);
    assert.equal((okRes as unknown as { status: number }).status, 200, "快路径返回注入实现的响应");
    // 计数只作下界断言：飞行中的外部异步可能泄漏进窗口调用全局 fetch（绝对计数实证 flake）
    assert.ok(fastCalls >= 1, "快路径到达注入 fetch 至少一次");
    assert.equal(
      (okRes as unknown as { url: string }).url,
      "https://gw.test/fast",
      "url 原样透传到 fetch",
    );

    // 慢路径：超过 timeoutMs 的延迟 -> 返回时已观察到 abort
    // （delayMs 远大于 timeoutMs=20：防微任务风暴推迟 abort 定时器）
    let slowCalls = 0;
    globalThis.fetch = (async (_url: unknown, opts: { signal?: AbortSignal } | undefined) => {
      slowCalls += 1;
      await new Promise((r) => setTimeout(r, 500));
      return { status: 200, ok: true, aborted: opts?.signal?.aborted ?? null };
    }) as unknown as typeof fetch;
    const slowRes = await fetchWithTimeout("https://gw.test/slow", 20);
    assert.ok(slowCalls >= 1, "慢路径到达注入 fetch 至少一次");
    assert.equal((slowRes as unknown as { aborted: boolean }).aborted, true,
      "超过 timeoutMs 后 controller.abort 已触发");

    // 默认参数形态：省略 timeoutMs 与 init 仍完成调用
    // （与 fast/slow 同理用下界断言：飞行中的外部异步可能泄漏进窗口调用全局 fetch）
    let defCalls = 0;
    globalThis.fetch = (async () => { defCalls += 1; return { status: 204 }; }) as unknown as typeof fetch;
    await fetchWithTimeout("https://gw.test/def");
    assert.ok(defCalls >= 1, "默认参数下仍走 fetch 至少一次");
  } finally {
    globalThis.fetch = savedFetch;
  }
}

packages/dsh-provider-usage/test/unit-co.source:
// @ts-nocheck
/**
 * dsh-provider-usage — unit：契约辅助纯函数。
 *
 * 覆盖：safeSegment（路径安全段）、sseData（SSE 序列化）、
 * parseUserAdapters（防御式解析）、summarizeTextFromWindows /
 * levelFromWindows（v1 废弃但保留的辅助函数）、esc（HTML 转义）、
 * isUsageStatsAdapter / describeUsageStatsAdapterShape（v2 契约校验全分支，
 * #150 变异驱动加固）。
 */
import { assert } from "./helpers.ts";
console.error("EVAL-ORDER-TAG: CONTRACT");
import {
  safeSegment,
  sseData,
  parseUserAdapters,
  summarizeTextFromWindows,
  levelFromWindows,
  esc,
  isUsageStatsAdapter,
  describeUsageStatsAdapterShape,
  ADAPTER_CONTRACT_VERSION,
  ERROR_CODES,
} from "../lib/index.js";

// ---------------------------------------------------------------- safeSegment

assert.equal(safeSegment("hello-world"), "hello-world", "字母数字连字符原样保留");
assert.equal(safeSegment("a.b_c"), "a.b_c", "点和下划线保留");
assert.equal(safeSegment("a/b\\c"), "a_b_c", "路径分隔符替换为下划线");
assert.equal(safeSegment("a b\tc"), "a_b_c", "空白字符替换为下划线");
assert.equal(safeSegment("中文/测试"), "_____", "非 ASCII 字符与路径分隔符全替换为下划线");
assert.equal(safeSegment(""), "unknown", "空字符串回退 unknown");
assert.equal(safeSegment("!@#$%^"), "______", "全部特殊字符替换为下划线");

// ---------------------------------------------------------------- sseData

assert.equal(sseData({ a: 1 }), "data: {\"a\":1}\n\n", "JSON SSE 序列化");
assert.equal(sseData("hello"), "data: \"hello\"\n\n", "字符串 SSE 带转义");
assert.equal(sseData([1, 2, 3]), "data: [1,2,3]\n\n", "数组 SSE 序列化");
assert.equal(sseData(null), "data: null\n\n", "null SSE 序列化");

// ---------------------------------------------------------------- parseUserAdapters

assert.deepEqual(parseUserAdapters(undefined), [], "undefined 返回空数组");
assert.deepEqual(parseUserAdapters(""), [], "空字符串返回空数组");
assert.deepEqual(parseUserAdapters("not json"), [], "非法 JSON 返回空数组");
assert.deepEqual(parseUserAdapters("[]"), [], "裸数组（非对象）返回空数组");
assert.deepEqual(parseUserAdapters('{"adapters": "not array"}'), [], "adapters 非数组返回空数组");
assert.deepEqual(parseUserAdapters('{"adapters": [{"id":"a","providers":["p1"],"file":"/x.mjs"}]}'), [
  { id: "a", label: "a", providers: ["p1"], file: "/x.mjs" },
], "合法条目解析");
assert.deepEqual(parseUserAdapters('{"adapters": [{"id":"","providers":["p1"],"file":"/x.mjs"}]}'), [],
  "空 id 条目丢弃");
assert.deepEqual(parseUserAdapters('{"adapters": [{"id":"a","providers":[],"file":"/x.mjs"}]}'), [],
  "空 providers 条目丢弃");
assert.deepEqual(parseUserAdapters('{"adapters": [{"id":"a","providers":["p1"],"file":""}]}'), [],
  "空 file 条目丢弃");
assert.deepEqual(parseUserAdapters('{"adapters": [{"id":"a","providers":["p1"],"file":"/x.mjs","label":"My Adp"}]}'), [
  { id: "a", label: "My Adp", providers: ["p1"], file: "/x.mjs" },
], "label 保留");
assert.deepEqual(parseUserAdapters('{"adapters": [{"id":"a","providers":["p1",""],"file":"/x.mjs"}]}'), [
  { id: "a", label: "a", providers: ["p1"], file: "/x.mjs" },
], "空 provider 字符串过滤");

// ---------------------------------------------------------------- summarizeTextFromWindows (deprecated)

assert.equal(summarizeTextFromWindows(undefined), "", "undefined 窗口返回空");
assert.equal(summarizeTextFromWindows([]), "", "空数组返回空");
assert.equal(summarizeTextFromWindows([{ key: "5h", name: "5h 滚动", percent: 5 }]), "5h 滚动 5%",
  "单窗口百分比展示");
assert.equal(summarizeTextFromWindows([{ key: "w", name: "每周", percent: 80 }]), "每周 80%",
  "整百分比无小数");
assert.equal(summarizeTextFromWindows([{ key: "r", name: "5h 滚动", percent: 5 }, { key: "w", name: "每周", percent: null }]),
  "5h 滚动 5% · 每周 --", "null 百分比显示 --");

// ---------------------------------------------------------------- levelFromWindows (deprecated)

assert.equal(levelFromWindows(undefined), "off", "undefined 窗口返回 off");
assert.equal(levelFromWindows([]), "off", "空数组返回 off");
assert.equal(levelFromWindows([{ key: "r", percent: 10 }]), "ok", "10% → ok");
assert.equal(levelFromWindows([{ key: "r", percent: 80 }]), "warn", "80% → warn");
assert.equal(levelFromWindows([{ key: "r", percent: 95 }]), "err", "95% → err");
assert.equal(levelFromWindows([{ key: "r", percent: 100 }]), "err", "100% → err");
assert.equal(levelFromWindows([{ key: "r", percent: null }]), "off", "null 百分比 → off");
assert.equal(levelFromWindows([{ key: "r", percent: 10 }, { key: "w", percent: 90 }]), "warn",
  "多窗口取最差（90 → warn，≥80 即为 warn）");
assert.equal(levelFromWindows("not array" as unknown as Parameters<typeof levelFromWindows>[0]), "off",
  "非数组输入返回 off（#150）");
assert.equal(levelFromWindows([{ key: "r", percent: 79.9 }]), "ok", "79.9 < 80 → ok 边界（#150）");
assert.equal(levelFromWindows([{ key: "r", percent: 94.9 }]), "warn", "94.9 < 95 → warn 边界（#150）");
assert.equal(levelFromWindows([{ key: "r" }]), "off", "缺 percent 字段 → off（#150）");
assert.equal(levelFromWindows([{ key: "r", percent: 30 }, { key: "w", percent: null }]), "ok",
  "null 混合窗口只计数值项（#150）");

// ---------------------------------------------------------------- esc（#150）

assert.equal(esc(null), "", "null 转义为空串");
assert.equal(esc(undefined), "", "undefined 转义为空串");
assert.equal(esc(""), "", "空字符串原样");
assert.equal(esc("plain"), "plain", "无特殊字符原样");
assert.equal(esc("<a>"), "&lt;a&gt;", "尖括号转义");
assert.equal(esc('a"b'), "a&quot;b", "双引号转义");
assert.equal(esc("a'b"), "a&#39;b", "单引号转义");
assert.equal(esc("a&b"), "a&amp;b", "与号转义");
assert.equal(esc('<script>&"\'</script>'),
  "&lt;script&gt;&amp;&quot;&#39;&lt;/script&gt;", "五类实体一次全转义");
assert.equal(esc(42), "42", "数字经 String() 后转义");
assert.equal(esc(true), "true", "布尔经 String() 后转义");

// ---------------------------------------------------------------- isUsageStatsAdapter 全条件穷举（#150）

function validAdapter(): Record<string, unknown> {
  return {
    version: ADAPTER_CONTRACT_VERSION,
    name: "my-adapter",
    providers: ["p1"],
    fetchData: () => {},
    formatCapsule: () => "",
    formatPanel: () => "",
  };
}

assert.equal(isUsageStatsAdapter(validAdapter()), true, "完整合法对象通过校验");

// 非对象侧
assert.equal(isUsageStatsAdapter(null), false, "null 拒绝");
assert.equal(isUsageStatsAdapter(undefined), false, "undefined 拒绝");
assert.equal(isUsageStatsAdapter(42), false, "数字拒绝");
assert.equal(isUsageStatsAdapter("str"), false, "字符串拒绝");
assert.equal(isUsageStatsAdapter([]), false, "数组（无 version 字段）拒绝");

// version 条件两侧
{
  const a = validAdapter();
  a.version = 1;
  assert.equal(isUsageStatsAdapter(a), false, "version=1（旧契约版本）拒绝");
}
{
  const a = validAdapter();
  a.version = "2";
  assert.equal(isUsageStatsAdapter(a), false, "version 为字符串严格比较拒绝");
}
{
  const a = validAdapter();
  delete a.version;
  assert.equal(isUsageStatsAdapter(a), false, "缺 version 拒绝");
}

// name 条件：类型 / 最短长度 / 正则白名单 / 最长长度
{
  const a = validAdapter();
  a.name = 123;
  assert.equal(isUsageStatsAdapter(a), false, "name 非字符串拒绝");
}
{
  const a = validAdapter();
  a.name = "a";
  assert.equal(isUsageStatsAdapter(a), false, "name 单字符拒绝（length>=2）");
}
{
  const a = validAdapter();
  a.name = "ab";
  assert.equal(isUsageStatsAdapter(a), true, "name 两字符通过（regex 下界）");
}
{
  const a = validAdapter();
  a.name = "a".repeat(64);
  assert.equal(isUsageStatsAdapter(a), true, "name 64 字符通过（regex 上界）");
}
{
  const a = validAdapter();
  a.name = "a".repeat(65);
  assert.equal(isUsageStatsAdapter(a), false, "name 65 字符拒绝（regex 上界外）");
}
{
  const a = validAdapter();
  a.name = "a b";
  assert.equal(isUsageStatsAdapter(a), false, "name 含空格拒绝（白名单外）");
}
{
  const a = validAdapter();
  a.name = "适配器";
  assert.equal(isUsageStatsAdapter(a), false, "name 含中文拒绝（白名单外）");
}

// providers 条件：非数组 / 空数组 / 元素类型 / 空串元素
{
  const a = validAdapter();
  a.providers = "p1";
  assert.equal(isUsageStatsAdapter(a), false, "providers 非数组拒绝");
}
{
  const a = validAdapter();
  a.providers = [];
  assert.equal(isUsageStatsAdapter(a), false, "providers 空数组拒绝");
}
{
  const a = validAdapter();
  a.providers = [1];
  assert.equal(isUsageStatsAdapter(a), false, "providers 元素非字符串拒绝");
}
{
  const a = validAdapter();
  a.providers = [""];
  assert.equal(isUsageStatsAdapter(a), false, "providers 空串元素拒绝");
}
{
  const a = validAdapter();
  a.providers = ["p1", ""];
  assert.equal(isUsageStatsAdapter(a), false, "providers 多元素含空串拒绝");
}

// 三函数条件
for (const fn of ["fetchData", "formatCapsule", "formatPanel"] as const) {
  const a = validAdapter();
  delete a[fn];
  assert.equal(isUsageStatsAdapter(a), false, `缺 ${fn} 拒绝`);
  const b = validAdapter();
  b[fn] = "not-fn";
  assert.equal(isUsageStatsAdapter(b), false, `${fn} 非函数拒绝`);
}

// ---------------------------------------------------------------- describeUsageStatsAdapterShape 全分支（#150）

assert.equal(describeUsageStatsAdapterShape(null), "导出不是对象（null）", "null 描述文案");
assert.equal(describeUsageStatsAdapterShape(undefined), "导出不是对象（undefined）", "undefined 描述文案");
assert.equal(describeUsageStatsAdapterShape(42), "导出不是对象（number）", "number 描述文案");
assert.equal(describeUsageStatsAdapterShape("s"), "导出不是对象（string）", "string 描述文案");
assert.equal(describeUsageStatsAdapterShape(validAdapter()), null, "合法形状返回 null");

assert.equal(describeUsageStatsAdapterShape({}), [
  "version 必须 === 2（实际 undefined）",
  "name（2-64 位字母数字下划线连字符）",
  "providers（非空字符串数组）",
  "fetchData（函数）",
  "formatCapsule（函数）",
  "formatPanel（函数）",
].join("、"), "全缺时六项按序合并");

{
  const a = validAdapter();
  a.version = 3;
  const detail = describeUsageStatsAdapterShape(a);
  assert.ok(detail !== null && detail.startsWith("version 必须 === 2（实际 3）"),
    "version 错误含期望值与实际值");
  assert.ok(detail !== null && !detail.includes("name"), "仅 version 缺陷时不报 name");
}
{
  const a = validAdapter();
  a.name = "x!";
  assert.ok(describeUsageStatsAdapterShape(a)?.includes("name（2-64 位字母数字下划线连字符）") === true,
    "name 白名单外的明细文案");
}

// ---------------------------------------------------------------- ERROR_CODES 全量清单（#150 分片 2）

assert.deepEqual(ERROR_CODES, [
  "no-provider",
  "no-adapter",
  "no-enabled-adapter",
  "no-api-key",
  "unauthorized",
  "timeout",
  "network",
  "bad-data",
  "bad-json",
  "adapter-load-failed",
  "adapter-crash",
  "adapter-timeout",
], "错误码清单逐项锁定（顺序与内容均不可变）");

// ---------------------------------------------------------------- isUsageStatsAdapter 补充边界（#150 分片 2）

{
  // String 包装对象：typeof 非 string，但 .length 与 regex.test 均可通过，
